pub(super) fn show_remote_companion(&mut self, ui: &mut egui::Ui) {
    let gateway_endpoint = self
        .remote_server
        .as_ref()
        .map(|server| server.endpoint().to_owned());
    if let Some(endpoint) = gateway_endpoint.as_deref()
        && self.remote_publication.mode() == RemotePublicationMode::TailscaleServe
    {
        self.remote_publication.maintain(endpoint);
        if self.remote_publication.poll() {
            ui.ctx().request_repaint();
        }
        if matches!(
            self.remote_publication.state(),
            TailscalePublicationState::Checking
        ) {
            ui.ctx()
                .request_repaint_after(std::time::Duration::from_millis(100));
        }
    }

    let mode = self.remote_publication.mode();
    let tailscale_state = self.remote_publication.state().clone();
    let effective_base = match mode {
        RemotePublicationMode::Manual => self.remote_phone_url_base.clone(),
        RemotePublicationMode::TailscaleServe => {
            tailscale_state.origin().unwrap_or_default().to_owned()
        }
    };
    let phone_url = self
        .remote_server
        .as_ref()
        .map(|server| server.phone_url(&effective_base));
    let ready = phone_url.as_ref().is_some_and(Result::is_ok);
    let mut copy_phone_url = None;
    let mut setup_tailscale = false;
    let mut retry_tailscale = false;

    theme::card(ui, |ui| {
        ui.horizontal_wrapped(|ui| {
            ui.strong("Phone access");
            let (tone, label) = if self.remote_server.is_none() {
                (theme::StatusTone::Blocked, "Gateway unavailable")
            } else if ready {
                (theme::StatusTone::Ready, "Ready")
            } else {
                (theme::StatusTone::Attention, "Setup required")
            };
            theme::status_pill(ui, tone, label);
        });

        if self.remote_server.is_none() {
            theme::hint(
                ui,
                "The loopback Remote AI Studio gateway could not start, so there is nothing safe to publish yet. Restart the Editor or fix the local gateway failure before configuring private access.",
            );
            return;
        }

        match mode {
            RemotePublicationMode::TailscaleServe => {
                ui.horizontal_wrapped(|ui| {
                    ui.label("Private network");
                    ui.strong("Tailscale");
                    theme::status_pill(
                        ui,
                        tailscale_publication_tone(&tailscale_state),
                        tailscale_state.label(),
                    );
                });
                theme::hint(ui, tailscale_state.message());
                match tailscale_state {
                    TailscalePublicationState::Checking => {
                        ui.horizontal(|ui| {
                            ui.spinner();
                            ui.small("Publishing the current loopback gateway…");
                        });
                    }
                    TailscalePublicationState::SetupRequired => {
                        if ui.button("Set up private access").clicked() {
                            retry_tailscale = true;
                        }
                    }
                    TailscalePublicationState::Ready { .. } => {}
                    _ => {
                        if ui.button("Retry").clicked() {
                            retry_tailscale = true;
                        }
                    }
                }
            }
            RemotePublicationMode::Manual if ready => {
                theme::field_row(
                    ui,
                    "Private network",
                    egui::RichText::new("Manual HTTPS origin · Ready").strong(),
                );
                theme::hint(
                    ui,
                    "GameEngine is using the HTTPS origin you supplied for a private reverse proxy.",
                );
            }
            RemotePublicationMode::Manual => {
                theme::hint(
                    ui,
                    "Tailscale Serve can publish AI Studio privately without making you track the Editor's dynamic gateway port. Tailscale remains optional.",
                );
                if ui.button("Set up private access").clicked() {
                    setup_tailscale = true;
                }
                if let Some(Err(error)) = phone_url.as_ref()
                    && !self.remote_phone_url_base.trim().is_empty()
                {
                    theme::hint(ui, error.reason());
                }
            }
        }

        if let Some(Ok(url)) = phone_url.as_ref() {
            ui.add_space(6.0);
            theme::field_row(
                ui,
                "Publishing",
                egui::RichText::new("AI Studio · Ready").strong(),
            );
            theme::caption(ui, "Phone URL");
            match masked_phone_url(&effective_base) {
                Ok(masked) => {
                    theme::selectable_text(ui, egui::RichText::new(masked).monospace());
                }
                Err(error) => theme::hint(ui, error.reason()),
            }
            if ui.button("Copy phone URL").clicked() {
                copy_phone_url = Some(url.clone());
            }
            ui.small("Your phone must be connected to the same private network.");
            theme::spec_note(
                ui,
                "The copied URL is a credential",
                "The access token is masked on screen and appears only in the copied URL. It authorizes this Remote AI Studio session; it does not replace Agent Host permissions.",
            );
        }
    });

    if setup_tailscale {
        match self.remote_publication.select_tailscale() {
            Ok(()) => {
                self.remote_publication.retry();
                ui.ctx().request_repaint();
            }
            Err(_) => {
                self.status = Some(
                    "Could not save the private-access selection on this machine.".to_owned(),
                );
            }
        }
    }
    if retry_tailscale {
        self.remote_publication.retry();
        ui.ctx().request_repaint();
    }
    if let Some(url) = copy_phone_url {
        ui.ctx().copy_text(url);
        self.status = Some("Phone URL copied. It carries the session access token.".to_owned());
    }

    self.show_remote_manual_configuration(ui);
    self.show_remote_advanced(ui);
}

/// Draws the vendor-neutral HTTPS publication path retained by ADR 0164.
fn show_remote_manual_configuration(&mut self, ui: &mut egui::Ui) {
    let configured = !self.remote_phone_url_base.trim().is_empty();
    let mut use_manual = false;
    let mut base_edited = false;
    egui::CollapsingHeader::new("Configure manually")
        .id_salt("ai_studio_remote_manual")
        .default_open(
            self.remote_publication.mode() == RemotePublicationMode::Manual && configured,
        )
        .show(ui, |ui| {
            ui.small("Use another private network or HTTPS reverse proxy. The gateway remains bound to loopback; enter only the externally published HTTPS origin.");
            theme::caption(ui, "Private HTTPS origin");
            let response = ui.add(
                egui::TextEdit::singleline(&mut self.remote_phone_url_base)
                    .desired_width(f32::INFINITY)
                    .hint_text("https://my-pc.example-private-network.test"),
            );
            if response.lost_focus() {
                base_edited = true;
            }
            if self.remote_publication.mode() != RemotePublicationMode::Manual
                && ui.button("Use manual configuration").clicked()
            {
                use_manual = true;
            }
            if let Some(server) = self.remote_server.as_ref()
                && let Err(error) = server.phone_url(&self.remote_phone_url_base)
                && configured
            {
                theme::hint(ui, error.reason());
            }
        });
    if base_edited || use_manual {
        if self.remote_publication.select_manual().is_err() {
            self.status = Some(
                "Could not save the manual private-access selection on this machine."
                    .to_owned(),
            );
        }
        self.save_preferences();
    }
}
